function seededRandom(seed){let n=seed>>>0;return ()=>{n+=0x6D2B79F5;let t=n;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296}}
function cityWorld(){if(!s.worldSeed)s.worldSeed=(Math.floor(Math.random()*4294967295)^Date.now())>>>0||1;if(house.citySeed===s.worldSeed&&house.chunks)return house.chunks;house.chunks=generateCityChunks(s.worldSeed,cityPlaces);house.citySeed=s.worldSeed;for(let c of house.chunks){let p=cityPlaces.find(p=>p.id===c.id);rooms[c.id]=p.name;spawn[c.id]=[c.x,c.z+3,Math.PI]}rooms.city='The silent city';spawn.city=[0,-15,Math.PI];return house.chunks}
function cityProgress(){return s.cityProgress||(s.cityProgress={})}
function cityVenue(id){let p=cityPlaces.find(p=>p.id===id);if(!p)return;const inspected=!!cityProgress()[id];modal(p.name,inspected?(p.choices.length?'The evidence is waiting. You can make a final choice here, or keep exploring.':'Your discovery is recorded. Take another look, or keep exploring.'):p.clue,[['Investigate the evidence',()=>{let first=!cityProgress()[id];cityProgress()[id]=true;save();modal(p.name+' · evidence',p.clue+(p.choices.length?'\n\nBoth local endings are now available at this site.':'\n\nThe discovery is recorded. There are more streets beyond this one.'),[['Step away',close]]);if(first)queueSanity(6)}],...(inspected?p.choices.map((c,i)=>[c[0],()=>{modal('End this story here?',c[0]+' will finish this playthrough. Your ending stays in the ending journal.',[['Choose this ending',()=>ending('city:'+id+':'+i)],['Keep exploring',close]])}]):[]),['Keep exploring',close]])}
function cityEndingAllowed(id){let m=/^city:([a-z]+):([01])$/.exec(id);return !!(m&&cityPlaces.some(p=>p.id===m[1]&&p.choices[Number(m[2])])&&cityProgress()[m[1]])}
const previousEnding=ending;ending=function(id){if(!id.startsWith('city:'))return previousEnding(id);if(!cityEndingAllowed(id))return;const [,place,index]=id.split(':'),p=cityPlaces.find(p=>p.id===place),c=p.choices[Number(index)],number=13+cityPlaces.indexOf(p)*2+Number(index);s.ending={title:'Ending '+number+' · '+c[1],body:c[2]};save();showEnding()};
let endingBook=[];try{endingBook=JSON.parse(localStorage.getItem('spare-room-halloween-endings'))||[]}catch{}const previousEndingScreen=showEnding;showEnding=function(){if(s.ending&&!endingBook.some(e=>e.title===s.ending.title)){endingBook.push({title:s.ending.title,seed:s.worldSeed||0});try{localStorage.setItem('spare-room-halloween-endings',JSON.stringify(endingBook))}catch{}}previousEndingScreen()};
