const priorWalk=canWalk;canWalk=function(x,z){if(z>=-10.7)return priorWalk(x,z);if(!s.cityOpen||x<=CITY_BOUNDS.left+.2||x>=CITY_BOUNDS.right-.2||z<=CITY_BOUNDS.far+.2)return false;return !house.solids.some(b=>Math.abs(x-b.x)<b.w/2+.15&&Math.abs(z-b.z)<b.d/2+.15&&(house.jumpHeight||0)<b.y+b.h-.02&&(house.jumpHeight||0)+1.65>b.y)};
