const previousMap=showMap;showMap=function(){let chunks=cityWorld();modal('City map · '+worldCode(),'Twenty locations across four rows of city blocks. Six landmarks offer ending choices; fourteen new places hide unsettling discoveries. New games reshuffle the buildings and scenery.',[['World generation code',worldCodeMenu],['House and garden',()=>modal('House and grounds','Return to a familiar room.',Object.entries(rooms).filter(([id])=>['hall','kitchen','bedroom','spare','garden','shed'].includes(id)).map(([id,name])=>[name,()=>{if(['kitchen','bedroom','spare'].includes(id))house.doors[id]=true;[house.x,house.z,house.a]=spawn[id];house.jumpHeight=0;s.room=id;save();close()}]).concat([['Back to city map',()=>showMap()]]))],...chunks.map(c=>[cityPlaces.find(p=>p.id===c.id).name,()=>{s.cityOpen=true;[house.x,house.z,house.a]=spawn[c.id];house.jumpHeight=0;s.room=c.id;save();close()}]),['Ending journal',endingJournal],['Back',close]])};
