const streetMovement=updateMovement;updateMovement=function(dt){streetMovement(dt);if(house.z>=-11||s.ending||s.sanityLost)return;s.citySeen||(s.citySeen=[]);let district=houseRoom();if(!s.citySeen.includes(district)){s.citySeen.push(district);save();let messages=['A telephone rings inside a building with no windows. It stops when you stop moving.','Every traffic light changes to red, though there is no traffic.','Footsteps follow you for three paces after your own feet stop.','A silhouette in an upstairs window turns away before you can look at it.','The public clock counts backwards. It is almost the time you were born.'];say(messages[(s.worldSeed+s.citySeen.length)%messages.length]);drainSanity(3)}};
